func scalarBoxesInline(password []byte, salt [16]byte, cost uint) (result [23]byte) {
	if cost < 4 || cost > 16 || len(password) > 72 {
		panic("invalid scalar experiment input")
	}
	key := append(append([]byte(nil), password...), 0)
	words, salts := keyWords(key), keyWords(salt[:])
	c := boxesFirstState{p: p, s0: s0, s1: s1, s2: s2, s3: s3}
	scalarExpandBoxesInlineSalt(&c, &words, &salts)
	for rounds := 0; rounds < 1<<cost; rounds++ {
		scalarExpandBoxesInline(&c, &words)
		scalarExpandBoxesInline(&c, &salts)
	}
	text := [6]uint32{0x4f727068, 0x65616e42, 0x65686f6c, 0x64657253, 0x63727944, 0x6f756274}
	for block := range 3 {
		l, r := text[2*block], text[2*block+1]
		for range 64 {
			l, r = scalarEncryptBoxesInline(l, r, &c)
		}
		text[2*block], text[2*block+1] = l, r
	}
	var raw [24]byte
	for i, word := range text {
		binary.BigEndian.PutUint32(raw[i*4:], word)
	}
	copy(result[:], raw[:23])
	return
}
